	public ExamServiceReqExecuteControl(Inventec.Desktop.Common.Modules.Module moduleData, V_HIS_SERVICE_REQ serviceReq, bool _isChronic, DelegateSelectData reLoadServiceReq, List<HIS_SERE_SERV> sereServCurrentTreatment)
		: base(moduleData)
	{
		LogSystem.Info("ExamServiceReqExecuteControl. Init .1");
		InitializeComponent();
		try
		{
			SereServsCurrentTreatment = sereServCurrentTreatment;
			HisServiceReqView = serviceReq;
			this.moduleData = moduleData;
			isChronic = _isChronic;
			treatmentId = ((HisServiceReqView != null) ? HisServiceReqView.TREATMENT_ID : 0);
			this.reLoadServiceReq = reLoadServiceReq;
			SetCaptionByLanguageKey();
			LogSystem.Info("ExamServiceReqExecuteControl. Init .2");
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
	}

	private void ExamServiceReqExecuteControl_Load(object sender, EventArgs e)
	{
		try
		{
			if (moduleData != null)
			{
				LogSystem.Debug("ExamServiceReqExecuteControl_Load .1 this.moduleData RoomId" + moduleData.RoomId);
			}
			InitControlState();
			timeClose = new System.Windows.Forms.Timer();
			timeClose.Interval = 100;
			timeClose.Tick += timerClose_Tick;
			LogSystem.Debug("ExamServiceReqExecuteControl_Load .1");
			LogSystem.Debug(LogUtil.TraceData(LogUtil.GetMemberName(() => HisServiceReqView), HisServiceReqView));
			HisConfigCFG.LoadConfig();
			ResetEye();
			LoadSdaConfig();
			autoCheckIcd = HisConfigs.Get<long>("HIS.Desktop.Plugins.AutoCheckIcd");
			isAutoCheckIcd = autoCheckIcd == 1;
			currentIcds = (from p in BackendDataWorker.Get<HIS_ICD>()
				where p.IS_ACTIVE == 1 && p.IS_TRADITIONAL != 1
				select p into o
				orderby o.ICD_CODE
				select o).ToList();
			LogSystem.Debug("ExamServiceReqExecuteControl_Load .2");
			long num = HisConfigs.Get<long>("HIS.Desktop.ShowServerTimeByDefault");
			if (num == 1)
			{
				isTimeServer = true;
			}
			if (isTimeServer)
			{
				currentTime = param.Now;
			}
			LoadTreatmentByPatient();
			LoadDataTreatmentExt();
			LoadCurrentPatient();
			LogSystem.Debug("ExamServiceReqExecuteControl_Load .3");
			UCIcdInit();
			UCIcdCauseInit();
			InitUcIcdYHCT();
			InitUcSecondaryIcdYHCT();
			LogSystem.Debug("ExamServiceReqExecuteControl_Load .4");
			LoadTreatmentInfomation();
