	private void SpinKeyPress(object sender, KeyPressEventArgs e)
	{
		try
		{
			if (!char.IsControl(e.KeyChar) && !char.IsDigit(e.KeyChar) && e.KeyChar != '.' && e.KeyChar != ',')
			{
				e.Handled = true;
			}
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
	}

