	private void chkTreatmentFinish_CheckedChanged(object sender, EventArgs e)
	{
		try
		{
			if (isReturnCheckboxHosTreat)
			{
				chkTreatmentFinish.Checked = false;
			}
			else if (chkTreatmentFinish.Checked)
			{
				if (!ValidForButtonOtherClick())
				{
					chkTreatmentFinish.Checked = false;
					return;
				}
				if (!ValidAddress())
				{
					chkTreatmentFinish.Checked = false;
					return;
				}
				SetCheckExecute(set: true, chkTreatmentFinish, chkExamServiceAdd, chkHospitalize, chkExamFinish);
				ResetPrintExecuteExt();
				onClickSaveFormAsyncForOtherButtonClick();
				treatmentFinishProcessor = new ExamTreatmentFinishProcessor();
				TreatmentFinishInitADO treatmentFinishInitADO = new TreatmentFinishInitADO();
				treatmentFinishInitADO.BranchName = BranchDataWorker.Branch.BRANCH_NAME;
				if (moduleData != null)
				{
					treatmentFinishInitADO.moduleData = moduleData;
				}
				if (patient == null || patient.ID == 0)
				{
					LoadPatient();
				}
				if (patient != null)
				{
					if (!string.IsNullOrEmpty(patient.CMND_NUMBER))
					{
						treatmentFinishInitADO.CmndDate = patient.CMND_DATE;
						treatmentFinishInitADO.CmndNumber = patient.CMND_NUMBER;
						treatmentFinishInitADO.CmndPlace = patient.CMND_PLACE;
						treatmentFinishInitADO.DocumentType = "CMND";
					}
					else if (!string.IsNullOrEmpty(patient.CCCD_NUMBER))
					{
						treatmentFinishInitADO.CmndDate = patient.CCCD_DATE;
						treatmentFinishInitADO.CmndNumber = patient.CCCD_NUMBER;
						treatmentFinishInitADO.CmndPlace = patient.CCCD_PLACE;
						treatmentFinishInitADO.DocumentType = "CCCD";
					}
					treatmentFinishInitADO.CareerId = patient.CAREER_ID;
				}
				treatmentFinishInitADO.Treatment = treatment;
				treatmentFinishInitADO.TraditionalIcdCode = IcdCodeYHCT;
				treatmentFinishInitADO.TraditionalIcdName = IcdNameYHCT;
				treatmentFinishInitADO.TraditionalIcdText = IcdTextYHCT;
				treatmentFinishInitADO.TraditionalIcdSubCode = IcdSubCodeYHCT;
				GetTotalIcd();
				if (dicIcd != null && dicIcd.Count > 0)
				{
					Dictionary<string, string> dictionary = new Dictionary<string, string>();
					dictionary = ((!dicIcd.ContainsKey(icdDefaultFinish.ICD_CODE)) ? dicIcd : dicIcd.Where((KeyValuePair<string, string> o) => o.Key != icdDefaultFinish.ICD_CODE).ToDictionary((KeyValuePair<string, string> o) => o.Key, (KeyValuePair<string, string> o) => o.Value));
					treatmentFinishInitADO.Treatment.ICD_SUB_CODE = string.Join(";", dictionary.Keys);
					treatmentFinishInitADO.Treatment.ICD_TEXT = string.Join(";", dictionary.Values);
				}
				if (lstIcdText != null && lstIcdText.Count > 0)
				{
					HIS_TREATMENT hIS_TREATMENT = treatmentFinishInitADO.Treatment;
					hIS_TREATMENT.ICD_TEXT = hIS_TREATMENT.ICD_TEXT + ";" + string.Join(";", lstIcdText);
				}
				if (treatmentFinishInitADO.Treatment != null && string.IsNullOrEmpty(treatmentFinishInitADO.Treatment.SICK_LOGINNAME))
				{
					treatmentFinishInitADO.Treatment.SICK_LOGINNAME = ClientTokenManagerStore.ClientTokenManager.GetLoginName();
					treatmentFinishInitADO.Treatment.SICK_USERNAME = ClientTokenManagerStore.ClientTokenManager.GetUserName();
				}
				if (string.IsNullOrEmpty(treatmentFinishInitADO.Treatment.TREATMENT_METHOD))
				{
					treatmentFinishInitADO.Treatment.TREATMENT_METHOD = txtTreatmentInstruction.Text.Trim();
				}
				treatmentFinishInitADO.PatientPrograms = PatientProgramList;
				treatmentFinishInitADO.DataStores = DataStoreList;
				treatmentFinishInitADO.MediRecord = MediRecode;
				treatmentFinishInitADO.TreatmentEndTypeExts = GetTreatmentEndTypeExt();
				treatmentFinishInitADO.IcdCode = icdDefaultFinish.ICD_CODE;
				treatmentFinishInitADO.IcdName = icdDefaultFinish.ICD_NAME;
				treatmentFinishInitADO.moduleData = moduleData;
				V_HIS_ROOM v_HIS_ROOM = BackendDataWorker.Get<V_HIS_ROOM>().FirstOrDefault((V_HIS_ROOM o) => o.ID == moduleData.RoomId);
				treatmentFinishInitADO.IsBlockNumOrder = v_HIS_ROOM.IS_BLOCK_NUM_ORDER == 1;
				treatmentFinishInitADO.dlgGetIcdSubCode = GetIcdSubCode;
				treatmentFinishInitADO.Note = CurrentPatient.NOTE;
				if (HisConfigCFG.IsAutoSetIcdWhenFinishInOtherExam && HisServiceReqView.IS_MAIN_EXAM != 1)
				{
					treatmentFinishInitADO.IsAutoSetIcdWhenFinishInOtherExam = true;
				}
				if (HisServiceReqView != null)
				{
					treatmentFinishInitADO.Advise = HisServiceReqView.ADVISE;
					treatmentFinishInitADO.Conclusion = HisServiceReqView.CONCLUSION;
				}
				CommonParam commonParam = new CommonParam();
				HisSevereIllnessInfoFilter hisSevereIllnessInfoFilter = new HisSevereIllnessInfoFilter();
				hisSevereIllnessInfoFilter.TREATMENT_ID = treatment.ID;
				List<HIS_SEVERE_ILLNESS_INFO> list = new BackendAdapter(commonParam).Get<List<HIS_SEVERE_ILLNESS_INFO>>("api/HisSevereIllnessInfo/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, hisSevereIllnessInfoFilter, commonParam);
				if (list != null && list.Count > 0)
				{
					treatmentFinishInitADO.SevereIllNessInfo = list[0];
					HisEventsCausesDeathFilter hisEventsCausesDeathFilter = new HisEventsCausesDeathFilter();
					hisEventsCausesDeathFilter.SEVERE_ILLNESS_INFO_ID = list[0].ID;
					List<HIS_EVENTS_CAUSES_DEATH> list3 = (treatmentFinishInitADO.ListEventsCausesDeath = new BackendAdapter(commonParam).Get<List<HIS_EVENTS_CAUSES_DEATH>>("api/HisEventsCausesDeath/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, hisEventsCausesDeathFilter, commonParam));
				}
				if (isTimeServer)
				{
					treatmentFinishInitADO.Treatment.OUT_TIME = loadParam().Now;
				}
				ucTreatmentFinish = (UserControl)treatmentFinishProcessor.Run(treatmentFinishInitADO, currentTreatmentExt);
				LoadUCToPanelExecuteExt(ucTreatmentFinish, chkTreatmentFinish);
				validTreatmentMethod();
				_ = requiredControl;
				if (requiredControl == 1)
				{
					lblCaptionPathologicalProcess.AppearanceItemCaption.ForeColor = Color.Maroon;
				}
			}
			else
			{
				LoadUCToPanelExecuteExt(null, chkTreatmentFinish);
			}
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
	}

	private void validTreatmentMethod()
	{
		try
		{
			if (treatment.TDL_TREATMENT_TYPE_ID == 3 || treatment.TDL_TREATMENT_TYPE_ID == 2 || treatment.TDL_TREATMENT_TYPE_ID == 4)
			{
