	private void txtNextTreatmentInstructionCode_Validating(object sender, CancelEventArgs e)
	{
		try
		{
			string search = ((TextEdit)sender).Text.Trim();
			if (!string.IsNullOrEmpty(search))
			{
				List<HIS_NEXT_TREA_INTR> list = dataNextTreatmentInstructions.Where((HIS_NEXT_TREA_INTR o) => o.NEXT_TREA_INTR_CODE.Contains(search)).ToList();
				List<HIS_NEXT_TREA_INTR> list2 = ((list == null) ? null : ((list.Count > 1) ? list.Where((HIS_NEXT_TREA_INTR o) => o.NEXT_TREA_INTR_CODE == search).ToList() : list));
				if (list2 == null || list2.Count <= 0)
				{
					e.Cancel = true;
					return;
				}
				txtNextTreatmentInstructionCode.ErrorText = "";
				dxValidationProviderForLeftPanel.RemoveControlError(txtNextTreatmentInstructionCode);
				ValidationNextTreatmentInst(10, 500, isRequired: true);
			}
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
	}

