	private void txtIcdSubCode_KeyDown(object sender, KeyEventArgs e)
	{
		try
		{
			if (e.KeyCode == Keys.Return)
			{
				isShowGridIcdSub = false;
				popupControlContainer1.HidePopup();
				if (!ProccessorByIcdCode((sender as TextEdit).Text.Trim()))
				{
					e.Handled = true;
					return;
				}
				isShowGridIcdSub = false;
				ReloadIcdSubContainerByCodeChanged();
				txtIcdText.Focus();
				txtIcdText.SelectionStart = txtIcdText.Text.Length;
			}
			else if (e.KeyCode == Keys.Down)
			{
				int focusedRowHandle = 0;
				int rowCount = gvIcdSubCode.RowCount;
				if (rowCount > 1)
				{
					focusedRowHandle = 1;
				}
				Rectangle rectangle = new Rectangle(panelControlCauseIcd.Bounds.X, panelControlCauseIcd.Bounds.Y, panelControlCauseIcd.Bounds.Width, panelControlCauseIcd.Bounds.Height);
				popupControlContainer1.ShowPopup(new Point(rectangle.X + 110, rectangle.Bottom - 50));
				gvIcdSubCode.Focus();
				gvIcdSubCode.FocusedRowHandle = focusedRowHandle;
			}
			else
			{
				_ = e.KeyCode;
				if (true)
				{
					isShowSubIcd = true;
				}
			}
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
	}

