	private void txtIcdCodeCause_Validating(object sender, CancelEventArgs e)
	{
		try
		{
			if (!isAllowNoIcd)
			{
				return;
			}
			string search = ((TextEdit)sender).Text.Trim();
			if (!string.IsNullOrEmpty(search))
			{
				List<HIS_ICD> list = currentIcds.Where((HIS_ICD o) => o.ICD_CODE.Equals(search)).ToList();
				List<HIS_ICD> list2 = ((list == null) ? null : ((list.Count > 1) ? list.Where((HIS_ICD o) => o.ICD_CODE == search).ToList() : list));
				if (list2 == null || list2.Count <= 0)
				{
					e.Cancel = true;
					return;
				}
				txtIcdCodeCause.ErrorText = "";
				dxValidationProviderForLeftPanel.RemoveControlError(txtIcdCodeCause);
				ValidationICDCause(10, 500, !isAllowNoIcd);
			}
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
	}

