	private bool DelegateRunPrinter(string printTypeCode, bool isSaveAndShow, MPS.ProcessorBase.PrintConfig.PreviewType? PreviewType)
	{
		bool result = false;
		try
		{
			PrintTreatmentFinishProcessor printTreatmentFinishProcessor = ((!PreviewType.HasValue) ? new PrintTreatmentFinishProcessor(treatment, (currentModuleBase != null) ? currentModuleBase.RoomId : 0) : new PrintTreatmentFinishProcessor(treatment, (long?)((currentModuleBase != null) ? currentModuleBase.RoomId : 0), PreviewType.Value));
			if (printTypeCode == "Mps000010")
			{
				InPhieuHenKham(printTypeCode, printTreatmentFinishProcessor);
			}
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
		return result;
	}

	private void InPhieuHenKham(string printTypeCode, PrintTreatmentFinishProcessor _printTreatmentFinishProcessor)
	{
		try
		{
			_printTreatmentFinishProcessor.PrintMps000010(printTypeCode);
