	public object UcDHSTGetValue()
	{
		object result = null;
		try
		{
			DHSTADO dHSTADO = new DHSTADO();
			if (dtExecuteTime.EditValue != null)
			{
				dHSTADO.EXECUTE_TIME = Inventec.Common.DateTime.Convert.SystemDateTimeToTimeNumber(dtExecuteTime.DateTime);
			}
			if (spinBloodPressureMax.EditValue != null)
			{
				dHSTADO.BLOOD_PRESSURE_MAX = Parse.ToInt64(spinBloodPressureMax.Value.ToString());
			}
			if (spinBloodPressureMin.EditValue != null)
			{
				dHSTADO.BLOOD_PRESSURE_MIN = Parse.ToInt64(spinBloodPressureMin.Value.ToString());
			}
			if (spinBreathRate.EditValue != null)
			{
				dHSTADO.BREATH_RATE = Inventec.Common.Number.Get.RoundCurrency(spinBreathRate.Value, 2);
			}
			if (spinHeight.EditValue != null)
			{
				dHSTADO.HEIGHT = Inventec.Common.Number.Get.RoundCurrency(spinHeight.Value, 2);
			}
			if (spinChest.EditValue != null)
			{
				dHSTADO.CHEST = Inventec.Common.Number.Get.RoundCurrency(spinChest.Value, 2);
			}
			if (spinBelly.EditValue != null)
			{
				dHSTADO.BELLY = Inventec.Common.Number.Get.RoundCurrency(spinBelly.Value, 2);
			}
			if (spinPulse.EditValue != null)
			{
				dHSTADO.PULSE = Parse.ToInt64(spinPulse.Value.ToString());
			}
			if (spinTemperature.EditValue != null)
			{
				dHSTADO.TEMPERATURE = Inventec.Common.Number.Get.RoundCurrency(spinTemperature.Value, 2);
			}
			if (spinWeight.EditValue != null)
			{
				dHSTADO.WEIGHT = Inventec.Common.Number.Get.RoundCurrency(spinWeight.Value, 2);
			}
			if (spinSPO2.EditValue != null)
			{
				dHSTADO.SPO2 = Inventec.Common.Number.Get.RoundCurrency(spinSPO2.Value, 2) / 100m;
			}
			dHSTADO.NOTE = txtNote.Text.Trim();
			dHSTADO.IsVali = true;
			if (!CheckDhst(dHSTADO))
			{
				result = dHSTADO;
			}
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
		return result;
	}

	private bool CheckDhst(DHSTADO data)
	{
		bool flag = true;
		try
		{
			flag = flag && !data.PULSE.HasValue && !data.BLOOD_PRESSURE_MAX.HasValue && !data.BLOOD_PRESSURE_MIN.HasValue && !data.TEMPERATURE.HasValue && !data.BREATH_RATE.HasValue && !data.HEIGHT.HasValue && !data.WEIGHT.HasValue && !data.CHEST.HasValue && !data.BELLY.HasValue && !data.CAPILLARY_BLOOD_GLUCOSE.HasValue && !data.SPO2.HasValue;
		}
		catch (Exception ex)
		{
			flag = false;
			LogSystem.Error(ex);
		}
		LogSystem.Info("CheckDhst: " + flag);
		return flag;
	}

	public async Task UcDHSTValidateControl()
	{
		try
		{
			bool isRequired = false;
			bool isThan16YearOld = false;
			bool isRequiredWeight = false;
			bool lessthan16YearOld = false;
			if (requiredControl == 1 && (isChronic || (treatment != null && treatment.IS_CHRONIC == 1)))
			{
				isRequired = true;
			}
			LogSystem.Debug("UcDHSTValidateControl." + LogUtil.TraceData(LogUtil.GetMemberName(() => isRequired), isRequired));
			if (IsLessThan1YearOldOr6YearOld(HisServiceReqView.TDL_PATIENT_DOB))
			{
				CommonParam param = new CommonParam();
				HisPatientTypeAlterViewAppliedFilter filter = new HisPatientTypeAlterViewAppliedFilter
				{
					TreatmentId = treatmentId,
					InstructionTime = (Inventec.Common.DateTime.Get.Now() ?? 0)
				};
				V_HIS_PATIENT_TYPE_ALTER currentHisPatientTypeAlter = await new BackendAdapter(param).GetAsync<V_HIS_PATIENT_TYPE_ALTER>("/api/HisPatientTypeAlter/GetApplied", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, filter, param);
				if (currentHisPatientTypeAlter.PATIENT_TYPE_ID == HisPatientTypeCFG.PATIENT_TYPE_ID__BHYT || currentHisPatientTypeAlter.PATIENT_TYPE_ID == HisPatientTypeCFG.PATIENT_TYPE_ID__IS_FEE)
				{
					isRequiredWeight = true;
				}
			}
			if (IsThan16YearOld(HisServiceReqView.TDL_PATIENT_DOB))
			{
				isThan16YearOld = true;
			}
			if (IsThan16YearOldByTreatment())
			{
				lessthan16YearOld = true;
			}
			ValidateControlSpinEditWeight(spinWeight, Option: false, IsRequired: false);
			if (isRequired)
			{
				lciExecuteTime.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciWeight.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciHeight.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciBloodPressure.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciPulse.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciTemperature.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciBreathRate.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciBelly.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciChest.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciSpo2.AppearanceItemCaption.ForeColor = Color.Maroon;
				ValidateSingleControl(dtExecuteTime);
				ValidateControlSpinEdit(spinPulse);
				ValidateControlSpinBloodPressure(spinBloodPressureMax);
				ValidateControlSpinBloodPressure(spinBloodPressureMin);
				ValidateControlSpinEditWeight(spinWeight, Option: false, IsRequired: true);
				ValidateControlSpinEdit(spinHeight);
				ValidateControlSpinEdit(spinTemperature);
				ValidateControlSpinEdit(spinBreathRate);
				ValidateControlSpinEdit(spinChest);
				ValidateControlSpinEdit(spinBelly);
				ValidateControlSpinEdit(spinSPO2, IsValidControlSPO2, Inventec.Desktop.Common.LibraryMessage.MessageUtil.GetMessage(Inventec.Desktop.Common.LibraryMessage.Message.Enum.NguoiDungNhapDuLieuKhongHopLe));
				ValidateControlMaxLength(txtNote, 4000);
			}
			else if (isRequiredWeight)
			{
				lciWeight.AppearanceItemCaption.ForeColor = Color.Maroon;
				ValidateControlSpinEditWeight(spinWeight, Option: true, IsRequired: true);
			}
			string requiredPulseBloodPressure = HisConfigs.Get<string>("HIS.UC.DHST__REQUIRED_PULSE_BLOOD_PRESSURE");
			if (requiredPulseBloodPressure == "1" || (requiredPulseBloodPressure == "2" && isThan16YearOld))
			{
				lciPulse.AppearanceItemCaption.ForeColor = Color.Maroon;
				lciBloodPressure.AppearanceItemCaption.ForeColor = Color.Maroon;
				ValidateControlSpinEdit(spinPulse);
				ValidateControlSpinBloodPressure(spinBloodPressureMax);
				ValidateControlSpinBloodPressure(spinBloodPressureMin);
			}
			if (HisConfigCFG.IsRequiredTemperatureOption && lessthan16YearOld)
			{
				lciTemperature.AppearanceItemCaption.ForeColor = Color.Maroon;
			}
		}
		catch (Exception ex2)
		{
			Exception ex = ex2;
			LogSystem.Warn(ex);
		}
	}

	private bool IsValidControlSPO2()
	{
		bool result = false;
		try
		{
			if (spinSPO2.EditValue != null)
			{
				result = spinSPO2.Value > 0m && spinSPO2.Value <= 100m;
			}
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
		return result;
	}

	private void ValidateControlSpinEditWeight(SpinEdit control, bool Option, bool IsRequired)
	{
		try
		{
			WeightValidaionRule weightValidaionRule = new WeightValidaionRule();
			weightValidaionRule.spn = control;
			weightValidaionRule.IsRequired = IsRequired;
			weightValidaionRule.IsRequiredWeightOption = (Option ? IsRequiredWeightOption : 0);
			dxValidationProviderForLeftPanel.SetValidationRule(control, weightValidaionRule);
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
	}

	private void ValidateControlSpinEdit(SpinEdit control)
	{
		try
		{
			ControlEditValidationRule controlEditValidationRule = new ControlEditValidationRule();
