			spinChest.EditValue = null;
			spinBelly.EditValue = null;
			spinPulse.EditValue = null;
			spinTemperature.EditValue = null;
			spinWeight.EditValue = null;
			spinSPO2.EditValue = null;
			txtNote.Text = "";
		}
		catch (Exception ex)
		{
			LogSystem.Warn(ex);
		}
	}

