	private bool CheckExecuteExt(HisServiceReqExamUpdateSDO hisServiceReqSDO)
	{
		bool result = true;
		try
		{
			if (hisServiceReqSDO != null)
			{
				if (chkHospitalize.Checked && hisServiceReqSDO.HospitalizeSDO == null)
				{
					return false;
				}
				if (chkExamServiceAdd.Checked && hisServiceReqSDO.ExamAdditionSDO == null)
				{
					return false;
				}
				if (chkTreatmentFinish.Checked && hisServiceReqSDO.TreatmentFinishSDO == null)
				{
					return false;
				}
				HIS_TREATMENT hIS_TREATMENT = treatment;
				if (hisServiceReqSDO.ExamAdditionSDO != null && hIS_TREATMENT != null && hIS_TREATMENT.TDL_HEIN_CARD_NUMBER != null && hIS_TREATMENT.TDL_TREATMENT_TYPE_ID != 3 && hIS_TREATMENT.TDL_TREATMENT_TYPE_ID != 2)
				{
					V_HIS_EXECUTE_ROOM data = new V_HIS_EXECUTE_ROOM();
