	private bool ProcessExamServiceReqExecute(V_HIS_SERVICE_REQ HisServiceReqWithOrderSDO, HisServiceReqExamUpdateSDO examServiceReqUpdateSDO)
	{
		bool flag = true;
		try
		{
			bool flag2 = true;
			if (chkHospitalize.Checked)
			{
				long DepartmentID = WorkPlace.WorkPlaceSDO.FirstOrDefault((WorkPlaceSDO o) => o.RoomId == moduleData.RoomId).DepartmentId;
				HisServiceReqFilter hisServiceReqFilter = new HisServiceReqFilter();
				hisServiceReqFilter.TREATMENT_ID = treatmentId;
				hisServiceReqFilter.REQUEST_DEPARTMENT_ID = DepartmentID;
				List<HIS_SERVICE_REQ> list = new BackendAdapter(null).Get<List<HIS_SERVICE_REQ>>("api/HisServiceReq/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, hisServiceReqFilter, null);
				List<HIS_SERVICE_REQ> list2 = new List<HIS_SERVICE_REQ>();
				if (list != null && list.Count > 0)
				{
					foreach (long item in list.Select((HIS_SERVICE_REQ o) => o.INTRUCTION_TIME))
					{
						DateTime dateTime = Inventec.Common.DateTime.Convert.TimeNumberToSystemDateTime(item) ?? DateTime.Now;
						DateTime now = DateTime.Now;
						if (dateTime > now)
						{
							IEnumerable<HIS_SERVICE_REQ> collection = list.Where((HIS_SERVICE_REQ o) => o.INTRUCTION_TIME == item);
							list2.AddRange(collection);
						}
					}
				}
				if (list2 != null && list2.Count > 0)
				{
					flag2 = false;
					string text = string.Join(",", list2.Select((HIS_SERVICE_REQ o) => o.SERVICE_REQ_CODE).ToList().Distinct()).ToString();
					string dEPARTMENT_NAME = BackendDataWorker.Get<HIS_DEPARTMENT>().FirstOrDefault((HIS_DEPARTMENT o) => o.ID == DepartmentID).DEPARTMENT_NAME;
					HospitalizeExamADO hisDepartmentTranHospitalizeSDO = hospitalizeProcessor.GetValue(ucHospitalize) as HospitalizeExamADO;
					if (hisDepartmentTranHospitalizeSDO != null)
					{
						string dEPARTMENT_NAME2 = BackendDataWorker.Get<HIS_DEPARTMENT>().FirstOrDefault((HIS_DEPARTMENT o) => o.ID == hisDepartmentTranHospitalizeSDO.HisDepartmentTranHospitalizeSDO.DepartmentId).DEPARTMENT_NAME;
						string text2 = "Các y lệnh " + text + " " + dEPARTMENT_NAME + " có thời gian y lệnh lớn hơn thời gian hiện tại nhập viện của " + dEPARTMENT_NAME2 + ". Bạn có muốn tiếp tục?";
						flag2 = XtraMessageBox.Show(text2, "Thông Báo", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button2) == DialogResult.Yes;
					}
				}
			}
			flag = flag2;
			if (flag2 && HisServiceReqWithOrderSDO != null && examServiceReqUpdateSDO != null)
			{
				ProcessExamServiceReqDTO(ref examServiceReqUpdateSDO);
				flag = flag && ProcessExamAddition(ref examServiceReqUpdateSDO, HisServiceReqWithOrderSDO);
				ProcessHospitalize(ref examServiceReqUpdateSDO);
				flag = flag && ProcessTreatmentFinish(ref examServiceReqUpdateSDO);
				ProcessExamFinish(ref examServiceReqUpdateSDO);
				ProcessExamSereIcdDTO(ref examServiceReqUpdateSDO);
				ProcessExamSereNextTreatmentIntructionDTO(ref examServiceReqUpdateSDO);
				ProcessExamSereDHST(ref examServiceReqUpdateSDO);
				try
				{
					if (treatment != null && !string.IsNullOrEmpty(treatment.HOSPITALIZE_REASON_NAME) && examServiceReqUpdateSDO.TreatmentFinishSDO != null)
					{
						examServiceReqUpdateSDO.TreatmentFinishSDO.HospitalizeReasonCode = treatment.HOSPITALIZE_REASON_CODE ?? null;
						examServiceReqUpdateSDO.TreatmentFinishSDO.HospitalizeReasonName = treatment.HOSPITALIZE_REASON_NAME;
					}
				}
				catch (Exception ex)
				{
					LogSystem.Debug("Loi khi map du lieu vao TreatmentFinishSDO.HospitalizeReasonCode");
					LogSystem.Warn(ex);
				}
			}
		}
		catch (Exception ex2)
		{
			flag = false;
			LogSystem.Warn(ex2);
		}
		return flag;
	}

	private void ProcessExamServiceReqDTO(ref HisServiceReqExamUpdateSDO examServiceReqUpdateSDO)
	{
		try
		{
			examServiceReqUpdateSDO.Id = HisServiceReqView.ID;
			examServiceReqUpdateSDO.Advise = HisServiceReqView.ADVISE;
			examServiceReqUpdateSDO.Conclusion = HisServiceReqView.CONCLUSION;
			examServiceReqUpdateSDO.SickDay = Parse.ToInt64(spinNgayThuCuaBenh.Text ?? "0");
			examServiceReqUpdateSDO.HospitalizationReason = ((!string.IsNullOrEmpty(txtHospitalizationReason.Text.Trim())) ? txtHospitalizationReason.Text.Trim() : null);
			examServiceReqUpdateSDO.FullExam = ((!string.IsNullOrEmpty(txtKhamToanThan.Text.Trim())) ? txtKhamToanThan.Text.Trim() : null);
			examServiceReqUpdateSDO.PartExam = ((!string.IsNullOrEmpty(txtKhamBoPhan.Text.Trim())) ? txtKhamBoPhan.Text.Trim() : null);
			examServiceReqUpdateSDO.ProvisionalDiagnosis = ((!string.IsNullOrEmpty(txtProvisionalDianosis.Text.Trim())) ? txtProvisionalDianosis.Text.Trim() : null);
			examServiceReqUpdateSDO.PartExamCirculation = ((!string.IsNullOrEmpty(txtTuanHoan.Text.Trim())) ? txtTuanHoan.Text.Trim() : null);
			examServiceReqUpdateSDO.PartExamDigestion = ((!string.IsNullOrEmpty(txtTieuHoa.Text.Trim())) ? txtTieuHoa.Text.Trim() : null);
			examServiceReqUpdateSDO.PartExamEar = ((!string.IsNullOrEmpty(txtTai.Text.Trim())) ? txtTai.Text.Trim() : null);
			examServiceReqUpdateSDO.PartExamEarRightNormal = ((!string.IsNullOrEmpty(txtPART_EXAM_EAR_RIGHT_NORMAL.Text.Trim())) ? txtPART_EXAM_EAR_RIGHT_NORMAL.Text.Trim() : null);
			examServiceReqUpdateSDO.PartExamEarRightWhisper = ((!string.IsNullOrEmpty(txtPART_EXAM_EAR_RIGHT_WHISPER.Text.Trim())) ? txtPART_EXAM_EAR_RIGHT_WHISPER.Text.Trim() : null);
			examServiceReqUpdateSDO.PartExamEarLeftNormal = ((!string.IsNullOrEmpty(txtPART_EXAM_EAR_LEFT_NORMAL.Text.Trim())) ? txtPART_EXAM_EAR_LEFT_NORMAL.Text.Trim() : null);
			examServiceReqUpdateSDO.PartExamEarLeftWhisper = ((!string.IsNullOrEmpty(txtPART_EXAM_EAR_LEFT_WHISPER.Text.Trim())) ? txtPART_EXAM_EAR_LEFT_WHISPER.Text.Trim() : null);
			if (chkPART_EXAM_HORIZONTAL_SIGHT__BT.Checked)
			{
				examServiceReqUpdateSDO.PartExamHorizontalSight = 1L;
			}
			else if (chkPART_EXAM_HORIZONTAL_SIGHT__HC.Checked)
			{
				examServiceReqUpdateSDO.PartExamHorizontalSight = 2L;
			}
			else
			{
				examServiceReqUpdateSDO.PartExamHorizontalSight = null;
			}
			if (chkPART_EXAM_VERTICAL_SIGHT__BT.Checked)
			{
				examServiceReqUpdateSDO.PartExamVerticalSight = 1L;
			}
			else if (chkPART_EXAM_VERTICAL_SIGHT__HC.Checked)
			{
				examServiceReqUpdateSDO.PartExamVerticalSight = 2L;
			}
			else
			{
				examServiceReqUpdateSDO.PartExamVerticalSight = null;
			}
			if (chkPART_EXAM_EYE_BLIND_COLOR__BT.Checked)
			{
				examServiceReqUpdateSDO.PartExamEyeBlindColor = 1L;
			}
			else if (chkPART_EXAM_EYE_BLIND_COLOR__MMTB.Checked)
			{
				examServiceReqUpdateSDO.PartExamEyeBlindColor = 2L;
			}
			else if (chkPART_EXAM_EYE_BLIND_COLOR__MMD.Checked && chkPART_EXAM_EYE_BLIND_COLOR__MMXLC.Checked && chkPART_EXAM_EYE_BLIND_COLOR__MMV.Checked)
			{
				examServiceReqUpdateSDO.PartExamEyeBlindColor = 9L;
			}
			else if (chkPART_EXAM_EYE_BLIND_COLOR__MMXLC.Checked && chkPART_EXAM_EYE_BLIND_COLOR__MMV.Checked)
			{
				examServiceReqUpdateSDO.PartExamEyeBlindColor = 8L;
			}
			else if (chkPART_EXAM_EYE_BLIND_COLOR__MMD.Checked && chkPART_EXAM_EYE_BLIND_COLOR__MMV.Checked)
			{
				examServiceReqUpdateSDO.PartExamEyeBlindColor = 7L;
			}
			else if (chkPART_EXAM_EYE_BLIND_COLOR__MMD.Checked && chkPART_EXAM_EYE_BLIND_COLOR__MMXLC.Checked)
			{
				examServiceReqUpdateSDO.PartExamEyeBlindColor = 6L;
			}
			else if (chkPART_EXAM_EYE_BLIND_COLOR__MMV.Checked)
			{
				examServiceReqUpdateSDO.PartExamEyeBlindColor = 5L;
			}
			else if (chkPART_EXAM_EYE_BLIND_COLOR__MMXLC.Checked)
			{
