	private void CreateThreadPostApi()
	{
		Thread thread = new Thread(CallS);
		try
		{
			thread.Start();
			thread.Join();
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
			thread.Abort();
		}
	}

