				icdDefaultFinish.ICD_CODE = HisServiceReqResult.ServiceReq.ICD_CODE;
				icdDefaultFinish.ICD_NAME = HisServiceReqResult.ServiceReq.ICD_NAME;
				LoadCurrentPatient();
				if (HisServiceReqResult.TreatmentFinishResult != null)
				{
					treatment = HisServiceReqResult.TreatmentFinishResult;
