					reLoadServiceReq(HisServiceReqResult.ServiceReq);
				}
				btnPrint_ExamService.Enabled = true;
				if (HisServiceReqResult.HospitalizeResult != null && HisServiceReqResult.HospitalizeResult.Treatment != null)
				{
