	private bool DelegateRunPrinter(string printTypeCode, string fileName)
	{
		bool result = false;
		try
		{
			switch (printTypeCode)
			{
			case "Mps000174":
				LoadBieuMauPhieuYCBenhAnNgoaiTru(printTypeCode, fileName, ref result);
				break;
			case "Mps000007":
				LoadBieuMauPhieuYCKhamBenhVaoVien(printTypeCode, fileName, ref result);
				break;
			case "Mps000374":
				LoadBieuMauPhieuYCKhamBenhCapCuu(printTypeCode, fileName, ref result);
				break;
			case "Mps000362":
				LoadBieuMauPhieuBenhAnNgoaiChan(printTypeCode, fileName, ref result);
				break;
			case "Mps000010":
				LoadBieuMauGiayHenKham(printTypeCode, fileName, ref result);
				break;
			case "Mps000008":
				LoadBieuMauGiayRaVien(printTypeCode, fileName, ref result);
				break;
			case "Mps000011":
				LoadBieuMauGiayChuyenVien(printTypeCode, fileName, ref result);
				break;
			case "Mps000268":
				LoadBieuMauGiayBaoTu(printTypeCode, fileName, ref result);
				break;
			case "Mps000269":
				LoadBieuMauGiayNghiOm(printTypeCode, fileName, ref result);
				break;
			case "Mps000389":
				LoadBieuMauGiayHenMo(printTypeCode, fileName, ref result);
				break;
			case "Mps000401":
				LoadBieuMauGiayDongYXetNghiemHIV(printTypeCode, fileName, ref result);
				break;
			case "Mps000436":
				LoadBieuMauGiayXetNghiemViKhuanLao(printTypeCode, fileName, ref result);
				break;
			case "Mps000437":
				ExamServiceReqExcuteControl__Print__Sars_nCOV_2(printTypeCode, fileName, ref result);
				break;
			case "Mps000438":
				LoadBieuMauGiayXetNghiemDom(printTypeCode, fileName, ref result);
				break;
			case "Mps000315":
				LoadPhieuKiemTraKhamSucKhoeDinhKy(printTypeCode, fileName, ref result);
				break;
			case "Mps000478":
				ProcessPrintMps000478(printTypeCode, fileName, ref result);
				break;
			case "Mps000111":
				ProcessPrintMps000111(printTypeCode, fileName, ref result);
				break;
			case "Mps000485":
				ProcessPrintMps000485(printTypeCode, fileName, ref result);
				break;
			case "Mps000178":
				ProcessPrintMps000178(printTypeCode, fileName, ref result);
				break;
			}
		}
		catch (Exception ex)
		{
			LogSystem.Error(ex);
		}
		return result;
	}

	private void ProcessPrintMps000111(string printTypeCode, string fileName, ref bool result)
	{
		try
		{
			string printerName = "";
			if (GlobalVariables.dicPrinter.ContainsKey(printTypeCode))
			{
				printerName = GlobalVariables.dicPrinter[printTypeCode];
			}
			if (resultEPayment != null)
			{
				HisSereServFilter hisSereServFilter = new HisSereServFilter();
				hisSereServFilter.IDs = resultEPayment.SereServs.Select((V_HIS_SERE_SERV o) => o.ID).ToList();
				List<HIS_SERE_SERV> listSereServ = new BackendAdapter(new CommonParam()).Get<List<HIS_SERE_SERV>>("api/HisSereServ/Get", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, hisSereServFilter, null);
				V_HIS_PATIENT_TYPE_ALTER v_HIS_PATIENT_TYPE_ALTER = new V_HIS_PATIENT_TYPE_ALTER();
				if (patient != null)
				{
					HisPatientTypeAlterViewFilter hisPatientTypeAlterViewFilter = new HisPatientTypeAlterViewFilter();
					hisPatientTypeAlterViewFilter.TDL_PATIENT_ID = patient.ID;
					v_HIS_PATIENT_TYPE_ALTER = new BackendAdapter(new CommonParam()).Get<List<V_HIS_PATIENT_TYPE_ALTER>>("api/HisPatientTypeAlter/GetView", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, hisPatientTypeAlterViewFilter, null).FirstOrDefault();
				}
				HisDepartmentTranLastFilter hisDepartmentTranLastFilter = new HisDepartmentTranLastFilter();
				hisDepartmentTranLastFilter.TREATMENT_ID = resultEPayment.Transaction.TREATMENT_ID.Value;
				hisDepartmentTranLastFilter.BEFORE_LOG_TIME = System.Convert.ToInt64(DateTime.Now.ToString("yyyyMMddHHmmss"));
				V_HIS_DEPARTMENT_TRAN departmentTran = new BackendAdapter(new CommonParam()).Get<V_HIS_DEPARTMENT_TRAN>("api/HisDepartmentTran/GetLastByTreatmentId", HIS.Desktop.ApiConsumer.ApiConsumers.MosConsumer, hisDepartmentTranLastFilter, null);
				Mps000111PDO data = new Mps000111PDO(resultEPayment.Transaction, patient, null, listSereServ, departmentTran, v_HIS_PATIENT_TYPE_ALTER, treatment.TDL_PATIENT_TYPE_ID.Value);
				result = MpsPrinter.Run(new PrintData(printTypeCode, fileName, data, MPS.ProcessorBase.PrintConfig.PreviewType.PrintNow, printerName));
			}
		}
		catch (Exception ex)
		{
			WaitingManager.Hide();
			LogSystem.Error(ex);
		}
	}

	private void PrintProcess(PrintType printType)
	{
		try
		{
			switch (printType)
			{
			case PrintType.KHAM_BENH_VAO_VIEN:
				richEditorMain.RunPrintTemplate("Mps000007", DelegateRunPrinter);
				break;
			case PrintType.BENH_AN_CAP_CUU_MPS374:
				richEditorMain.RunPrintTemplate("Mps000374", DelegateRunPrinter);
				break;
			case PrintType.BENH_AN_NGOAI_TRU:
				richEditorMain.RunPrintTemplate("Mps000174", DelegateRunPrinter);
				break;
			case PrintType.IN_BENH_AN_NGOAI_CHAN:
				richEditorMain.RunPrintTemplate("Mps000362", DelegateRunPrinter);
				break;
			case PrintType.BIEU_MAU_KHAC_PHIEU_PTTT:
				LoadBieuMauKhacPhieuPTTT();
				break;
			case PrintType.PHIEU_TU_VAN:
				LoadBieuMauKhacPhieuTuVan();
				break;
			case PrintType.PHIEU_KHAM_BENH_CHUYEN_KHAM_PHONG_PTTT:
				LoadBieuMauKhacPhieuKBChuyenKhamPhongPTTT();
				break;
			case PrintType.BENH_AN_DIEU_TRI_NGOAI_TRU_PTTT_PHONG_KHAM_PTTT:
				LoadBenhAnDieuTriNgoaiTruPTTTPhongKhamPTTT();
				break;
			case PrintType.BANG_TRAC_NGHIEM_CO_VA_CAM_GIAC:
				LoadBangTracNghiemCoVaCamGiac();
				break;
			case PrintType.PHIEU_XAC_NHAN_DONG_Y_XET_NGHIEM_HIV_MPS401:
				DelegateRunPrinter("Mps000401", null);
				break;
			case PrintType.PHIEU_XET_NGHIEM_VI_KHUAN_LAO_MPS436:
				DelegateRunPrinter("Mps000436", null);
				break;
			case PrintType.PHIEU_XET_NGHIEM_XPertXPressSARsnCOV2_MPS437:
				DelegateRunPrinter("Mps000437", null);
				break;
			case PrintType.PHIEU_XET_NGHIEM_DOM_MPS438:
				DelegateRunPrinter("Mps000438", null);
				break;
			case PrintType.KHAM_SUC_KHOE_CAN_BO:
				richEditorMain.RunPrintTemplate("Mps000013", DelegateRunPrinter);
				break;
			case PrintType.IN_PHIEU_YEU_CAU:
				richEditorMain.RunPrintTemplate("Mps000025", DelegateRunPrinter);
				break;
			case PrintType.IN_GIAY_HEN_KHAM:
				richEditorMain.RunPrintTemplate("Mps000010", DelegateRunPrinter);
				break;
			case PrintType.YEU_CAU_KHAM_THEM:
				InPhieuYeuCauDichVu("Mps000071");
				break;
			case PrintType.YEU_CAU_KHAM:
				InPhieuYeuCauDichVu("Mps000001");
				break;
			case PrintType.IN_GIAY_CHUYEN_VIEN:
				richEditorMain.RunPrintTemplate("Mps000011", DelegateRunPrinter);
				break;
			case PrintType.IN_GIAY_RA_VIEN:
				richEditorMain.RunPrintTemplate("Mps000008", DelegateRunPrinter);
				break;
			case PrintType.IN_GIAY_BAO_TU:
				richEditorMain.RunPrintTemplate("Mps000268", DelegateRunPrinter);
				break;
			case PrintType.BANG_KE_NGOAI_TRU_BHYT:
				richEditorMain.RunPrintTemplate("Mps000120", DelegateRunPrinter);
				break;
			case PrintType.BANG_KE_NGOAI_TRU_VIEN_PHI:
				richEditorMain.RunPrintTemplate("Mps000122", DelegateRunPrinter);
				break;
			case PrintType.IN_GIAY_NGHI_OM:
				richEditorMain.RunPrintTemplate("Mps000269", DelegateRunPrinter);
				break;
			case PrintType.IN_PHIEU_HEN_MO:
				richEditorMain.RunPrintTemplate("Mps000389", DelegateRunPrinter);
				break;
			case PrintType.PHIEU_KIEM_TRA_KHAM_SUC_KHOE_DINH_KY:
				richEditorMain.RunPrintTemplate("Mps000315", DelegateRunPrinter);
				break;
			case PrintType.PHIEU_THU_THANH_TOAN:
				richEditorMain.RunPrintTemplate("Mps000111", DelegateRunPrinter);
				break;
			case PrintType.KET_QUA_XET_NGHIEM_TONG_HOP:
			case PrintType.GOP_DON_THUOC:
			case PrintType.DON_PHONG_KHAM_TONG_HOP:
			case PrintType.IN_GIAY_NGHI_DUONG_THAI:
			case PrintType.IN_GIAY_NGHI_HUONG_BHXH:
			case PrintType.TRICH_LUC:
			case PrintType.PHIEU_CHUYEN_VIEN:
			case PrintType.IN_DON_THUOC:
			case PrintType.TOM_TAT_Y_LENH_PTTT_VA_DON_THUOC:
				break;
			}
